   108      const styles = useThemeStyles();
   109      const {translate} = useLocalize();
   110      const listRef = useRef<RNSectionList<TItem, SectionWithIndexOffset<TItem>>>(null);
   111      const innerTextInputRef = useRef<RNTextInput | null>(null);
