   116      const [maxToRenderPerBatch, setMaxToRenderPerBatch] = useState(shouldUseDynamicMaxToRenderPerBatch ? 0 : CONST.MAX_TO_RENDER_PER_BATCH.DEFAULT);
   117      const [isInitialSectionListRender, setIsInitialSectionListRender] = useState(true);
