   349
   350      /**
   351       * This function is used to compute the layout of any given item in our list.
   352       * We need to implement it so that we can programmatically scroll to items outside the virtual render window of the SectionList.
   353       *
   354       * @param data - This is the same as the data we pass into the component
   355       * @param flatDataArrayIndex - This index is provided by React Native, and refers to a flat array with data from all the sections. This flat array has some quirks:
   356       *
   357       *     1. It ALWAYS includes a list header and a list footer, even if we don't provide/render those.
   358       *     2. Each section includes a header, even if we don't provide/render one.
   359       *
   360       *     For example, given a list with two sections, two items in each section, no header, no footer, and no section headers, the flat array might look something like this:
   361       *
   362       *     [{header}, {sectionHeader}, {item}, {item}, {sectionHeader}, {item}, {item}, {footer}]
   363       */
   364      const getItemLayout = (data: Array<SectionListData<TItem, SectionWithIndexOffset<TItem>>> | null, flatDataArrayIndex: number) => {
   365          const targetItem = flattenedSections.itemLayouts[flatDataArrayIndex];
   366
   367          if (!targetItem) {
   368              return {
   369                  length: 0,
   370                  offset: 0,
   371                  index: flatDataArrayIndex,
   372              };
   373          }
   374
   375          return {
   376              length: targetItem.length,
   377              offset: targetItem.offset,
   378              index: flatDataArrayIndex,
   379          };
   380      };
   381
   382      const renderSectionHeader = ({section}: {section: SectionListDataType<TItem>}) => {
   383          if (section.CustomSectionHeader) {
   384              return <section.CustomSectionHeader section={section} />;
   385          }
   386
   387          if (!section.title || isEmptyObject(section.data) || listHeaderContent) {
   388              return null;
   389          }
   390
   391          return (
   392              // Note: The `optionsListSectionHeader` style provides an explicit height to section headers.
   393              // We do this so that we can reference the height in `getItemLayout` –
   394              // we need to know the heights of all list items up-front in order to synchronously compute the layout of any given list item.
   395              // So be aware that if you adjust the content of the section header (for example, change the font size), you may need to adjust this explicit height as well.
   396              <View style={[styles.optionsListSectionHeader, styles.justifyContentCenter, sectionTitleStyles]}>
   397                  <Text style={[styles.ph5, styles.textLabelSupporting]}>{section.title}</Text>
   398              </View>
   399          );
   400      };
   401
   402      const header = () => (
