    11  const useSyncFocus = (ref: RefObject<View>, isFocused: boolean, shouldSyncFocus = true) => {
    12      // this hook can be used outside ScreenWrapperStatusContext (eg. in Popovers). So we to check if the context is present.
    13      // If we are outside context we don't have to look at transition status
    14      const contextValue = useContext(ScreenWrapperStatusContext);
    15
    16      const didScreenTransitionEnd = contextValue ? contextValue.didScreenTransitionEnd : true;
